import timeimport cv2def speed_tracking(v_km_s,track_id,cen_car,start_line, left_side_car,a_start_line,dict_cars_speed,counter_car,cadr_time,s,frame,x,y):    # Если находится слева от линии и потом пересекает линию, то добавляем в счетчик    if cen_car[0]<start_line[0]:        left_side_car.add(track_id)    if cen_car[0]>=a_start_line[0]:        start_time =time.time()        if len(dict_cars_speed[track_id]) == 0:            dict_cars_speed[track_id].append(start_time)    if cen_car[0] >= start_line[0] and track_id in left_side_car:        counter_car.add(track_id)        end_time = time.time()        if len(dict_cars_speed[track_id]) == 1:            dict_cars_speed[track_id].append(end_time)            delta_time = dict_cars_speed[track_id][-1] - dict_cars_speed[track_id][0]            v_m_s = s/delta_time            v_km_s = cadr_time*v_m_s        if v_km_s > 0:            cv2.putText(frame, str(v_km_s), (x, y+100),cv2.FONT_HERSHEY_SIMPLEX,2, (255, 0, 0), 2)